const files = import.meta.glob<{ path: string; date: string }>('../data/lastmod/*.json', { eager: true, import: 'default' });
const map: Record<string, { date: string }> = Object.fromEntries(Object.values(files).map((e) => [e.path, e]));

/**
 * The date a page's content last changed (YYYY-MM-DD), for the sitemap's
 * <lastmod> and structured data's dateModified. The files in src/data/lastmod/
 * are generated by scripts/lastmod.mjs; see the notes there.
 */
export function lastmodFor(path: string): string {
  const entry = map[path];
  if (!entry) throw new Error(`No lastmod for ${path}: run node scripts/lastmod.mjs`);
  return entry.date;
}
